  num? target(ChecklistItem i){final b=i.recommendedQuantity;if(b==null)return null;final u=i.unit??'';if(u.contains('/ personne')||u.contains('par personne'))return b*(people==0?1:people);if(u.contains('/ enfant'))return b*(family['children']??0);if(u.contains('/ animal'))return b*pets;return b;}
