  Future<void> edit(ChecklistItem item) async {final current=stock[item.id]??KitStockEntry(itemId:item.id);final q=TextEditingController(text:current.quantityOwned.toString());DateTime? expiry=current.expiryDate;final result=await showModalBottomSheet<KitStockEntry>(context:context,isScrollControlled:true,backgroundColor:Colors.transparent,builder:(sheet)=>StatefulBuilder(builder:(context,setSheet)=>Container(padding:EdgeInsets.fromLTRB(20,12,20,MediaQuery.of(context).viewInsets.bottom+24),decoration:const BoxDecoration(color:Colors.white,borderRadius:BorderRadius.vertical(top:Radius.circular(26))),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Center(child:Container(width:42,height:4,decoration:BoxDecoration(color:Colors.black12,borderRadius:BorderRadius.circular(3)))),const SizedBox(height:18),Row(children:[Container(width:54,height:54,decoration:BoxDecoration(color:const Color(0xffe7f5f5),borderRadius:BorderRadius.circular(15)),child:Icon(iconFor(item),color:const Color(0xff087f83),size:30)),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(item.label,style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),if(target(item)!=null)Text('Recommandé pour votre foyer : ${target(item)} ${unit(item)}',style:const TextStyle(color:Color(0xff65747a))) ]))]),const SizedBox(height:20),Text('Ma quantité',style:Theme.of(context).textTheme.titleSmall?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:8),TextField(controller:q,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:InputDecoration(prefixIcon:IconButton(onPressed:(){final v=(num.tryParse(q.text)??0)-1;q.text=(v<0?0:v).toString();},icon:const Icon(Icons.remove)),suffixIcon:IconButton(onPressed:(){q.text=((num.tryParse(q.text)??0)+1).toString();},icon:const Icon(Icons.add)),suffixText:unit(item))),if(item.hasExpiry)...[const SizedBox(height:18),Text('Date de péremption',style:Theme.of(context).textTheme.titleSmall?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:8),ListTile(shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(14)),tileColor:const Color(0xfff2f6f7),leading:const Icon(Icons.calendar_month_outlined),title:Text(expiry==null?'Ajouter une date':date(expiry!)),trailing:expiry==null?const Icon(Icons.chevron_right):IconButton(icon:const Icon(Icons.close),onPressed:()=>setSheet(()=>expiry=null)),onTap:()async{final p=await showDatePicker(context:context,initialDate:expiry??DateTime.now().add(const Duration(days:180)),firstDate:DateTime.now().subtract(const Duration(days:3650)),lastDate:DateTime.now().add(const Duration(days:7300)));if(p!=null)setSheet(()=>expiry=p);}),const SizedBox(height:8),Row(children:[const Icon(Icons.notifications_active_outlined,size:18,color:Color(0xff087f83)),const SizedBox(width:8),Expanded(child:Text('Rappel ${item.expiryReminderDays} jours avant l’échéance',style:const TextStyle(fontWeight:FontWeight.w600)))])],const SizedBox(height:20),SizedBox(width:double.infinity,child:FilledButton(onPressed:(){Navigator.pop(sheet,KitStockEntry(itemId:item.id,quantityOwned:num.tryParse(q.text.replaceAll(',','.'))??0,expiryDate:expiry,updatedAt:DateTime.now()));},child:const Text('Enregistrer')))]))));q.dispose();if(result!=null){await store.saveKitStockEntry(result);if(mounted)setState(()=>stock[item.id]=result);}}

  @override Widget build(BuildContext context){final t=AppLocalizations.of(context);final all=widget.kit?kitItems:scenarioLists.entries.expand((e)=>e.value.map((x)=>ChecklistItem(id:'${e.key}-$x',label:x,category:e.key))).toList();final visible=!widget.kit?all:all.where((i){if(filter==1)return !done.contains(i.id);if(filter==2)return i.hasExpiry;return true;}).toList();return Scaffold(appBar:AppBar(title:Text(widget.kit?'Kit d’urgence':t.get('checklists'))),body:Column(children:[if(widget.kit)...[Padding(padding:const EdgeInsets.fromLTRB(16,6,16,10),child:Column(children:[Row(children:List.generate(3,(i)=>Expanded(child:Padding(padding:EdgeInsets.only(right:i<2?6:0),child:ChoiceChip(showCheckmark:false,label:Center(child:Text(['Tous','Manquants','Avec DLC'][i])),selected:filter==i,onSelected:(_)=>setState(()=>filter=i)))))),const SizedBox(height:14),ClipRRect(borderRadius:BorderRadius.circular(6),child:LinearProgressIndicator(value:all.isEmpty?0:done.length/all.length,minHeight:8,backgroundColor:const Color(0xffe5eeee))),const SizedBox(height:7),Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text('${done.length} / ${all.length} éléments prêts',style:const TextStyle(fontWeight:FontWeight.w800)),Text('$people pers. • $pets animal(aux)',style:const TextStyle(color:Color(0xff65747a),fontSize:12))])]))]else LinearProgressIndicator(value:all.isEmpty?0:done.length/all.length),Expanded(child:ListView.builder(padding:const EdgeInsets.fromLTRB(12,4,12,24),itemCount:visible.length,itemBuilder:(_,index){final item=visible[index];final checked=done.contains(item.id);final entry=stock[item.id];final tar=target(item);final u=unit(item);final expired=entry?.isExpired??false;final soon=item.hasExpiry&&(entry?.expiresWithin(item.expiryReminderDays)??false);return Card(margin:const EdgeInsets.only(bottom:8),child:InkWell(borderRadius:BorderRadius.circular(18),onTap:widget.kit?()=>edit(item):null,child:Padding(padding:const EdgeInsets.symmetric(horizontal:10,vertical:7)